// Some portions generated by Claude

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.RepositoryConnection;

/** SeqRepro corpus case target warmIdx(comma list, run twice) store: load, warm, update, run target. */
public class SeqRepro {
	public static void main(String[] a) throws Exception {
		DiffRunner.Case c = DiffRunner.parse(Path.of(a[0])).stream().filter(x -> x.id().equals(a[1])).findFirst()
				.orElseThrow();
		int target = Integer.parseInt(a[2]);
		List<Integer> warm = a[3].isEmpty() ? List.of()
				: java.util.Arrays.stream(a[3].split(",")).map(Integer::parseInt).toList();
		Path dir = Files.createTempDirectory(Path.of(System.getProperty("diff.tmp", "/tmp")), "seq");
		Repository repo = DiffRunner.open(a[4], dir);
		try (RepositoryConnection con = repo.getConnection()) {
			DiffRunner.load(con, c.data());
			for (int pass = 0; pass < 2; pass++) {
				for (int w : warm) {
					DiffRunner.run(con, c.queries().get(w).text());
				}
			}
			DiffRunner.update(con, c.update());
			if (a.length > 5 && !a[5].isEmpty()) {
				for (String w : a[5].split(",")) {
					DiffRunner.run(con, c.queries().get(Integer.parseInt(w)).text());
				}
			}
			System.out.println(DiffRunner.run(con, c.queries().get(target).text())[0]);
		} finally {
			DiffRunner.close(repo, dir);
		}
		System.exit(0);
	}
}
